'use client';

import React, { useEffect, useState, useCallback, useRef } from 'react';
import { Wallet, ArrowUpRight, TrendingUp, RefreshCw, Award, ArrowDownLeft, ShieldCheck, X, PlusCircle, Coins } from 'lucide-react';
import { useLanguage } from '../../components/LanguageContext';
import { motion, AnimatePresence } from 'framer-motion';

interface Transaction {
  id: string;
  type: 'credit' | 'debit';
  desc: string;
  amount: string;
  date: string;
  status: 'Completed' | 'Pending';
}

const WALLET_BALANCE_KEY = 'trayago_wallet_balance';
const WALLET_TXS_KEY = 'trayago_wallet_transactions';

// ── Count-up hook ──────────────────────────────────────────────────────────
function useCountUp(target: number, duration = 1200): number {
  const [value, setValue] = useState(0);
  const rafRef = useRef<number | null>(null);
  const startRef = useRef<number | null>(null);
  const startValRef = useRef(0);

  useEffect(() => {
    startValRef.current = 0;
    startRef.current = null;
    if (rafRef.current) cancelAnimationFrame(rafRef.current);

    const step = (ts: number) => {
      if (startRef.current === null) startRef.current = ts;
      const elapsed = ts - startRef.current;
      const progress = Math.min(elapsed / duration, 1);
      // Cubic ease-out
      const eased = 1 - Math.pow(1 - progress, 3);
      setValue(Math.round(startValRef.current + (target - startValRef.current) * eased));
      if (progress < 1) rafRef.current = requestAnimationFrame(step);
    };

    rafRef.current = requestAnimationFrame(step);
    return () => { if (rafRef.current) cancelAnimationFrame(rafRef.current); };
  }, [target, duration]);

  return value;
}

// ── Motion Variants ───────────────────────────────────────────────────────
const containerVariants = {
  hidden: { opacity: 0 },
  show: { opacity: 1, transition: { staggerChildren: 0.09, delayChildren: 0.04 } },
};

const cardVariants = {
  hidden: { opacity: 0, y: 20, scale: 0.97 },
  show: { opacity: 1, y: 0, scale: 1, transition: { type: 'spring' as const, stiffness: 260, damping: 22 } },
};

const txVariants = {
  hidden: { opacity: 0, x: -14 },
  show: (i: number) => ({
    opacity: 1, x: 0,
    transition: { delay: i * 0.06, type: 'spring' as const, stiffness: 280, damping: 22 },
  }),
};

const modalVariants = {
  hidden: { opacity: 0, scale: 0.93, y: 16 },
  show: { opacity: 1, scale: 1, y: 0, transition: { type: 'spring' as const, stiffness: 300, damping: 24 } },
  exit: { opacity: 0, scale: 0.95, y: 10, transition: { duration: 0.18 } },
};

export default function WalletPage() {
  const { t } = useLanguage();
  const [balance, setBalance] = useState<number>(1250);
  const [points, setPoints] = useState('150');
  const [userEmail, setUserEmail] = useState('traveler@trayago.com');
  const [loading, setLoading] = useState(false);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [showTopUp, setShowTopUp] = useState(false);
  const [topUpAmount, setTopUpAmount] = useState('');
  const [topUpError, setTopUpError] = useState('');

  const animatedBalance = useCountUp(balance, 1200);
  const animatedPoints = useCountUp(parseInt(points) || 0, 1000);

  // ── Sync states with localStorage ──
  const syncWalletData = useCallback(() => {
    try {
      const savedBalance = localStorage.getItem(WALLET_BALANCE_KEY);
      if (savedBalance !== null) {
        setBalance(Number(savedBalance));
      } else {
        localStorage.setItem(WALLET_BALANCE_KEY, '1250');
        setBalance(1250);
      }

      const savedTxs = localStorage.getItem(WALLET_TXS_KEY);
      if (savedTxs !== null) {
        setTransactions(JSON.parse(savedTxs));
      } else {
        const defaultTxs: Transaction[] = [
          {
            id: 'TX-9012',
            type: 'credit',
            desc: 'Referral Bonus Credit',
            amount: '+₹250.00',
            date: '28 May 2026',
            status: 'Completed',
          },
          {
            id: 'TX-9011',
            type: 'credit',
            desc: 'SignUp Promotional Reward',
            amount: '+₹1,000.00',
            date: '27 May 2026',
            status: 'Completed',
          },
        ];
        localStorage.setItem(WALLET_TXS_KEY, JSON.stringify(defaultTxs));
        setTransactions(defaultTxs);
      }
    } catch (e) {
      console.error('Failed to parse wallet data from localStorage:', e);
    }
  }, []);

  useEffect(() => {
    syncWalletData();

    // Listen to storage sync events across tabs
    const handleStorageChange = (e: StorageEvent) => {
      if (e.key === WALLET_BALANCE_KEY || e.key === WALLET_TXS_KEY) {
        syncWalletData();
      }
    };
    // Listen to local custom event triggers (e.g. from refund actions)
    window.addEventListener('storage', handleStorageChange);
    window.addEventListener('wallet-update', syncWalletData);

    // Load email
    try {
      const userRaw = localStorage.getItem('user');
      if (userRaw) {
        const parsed = JSON.parse(userRaw);
        if (parsed?.email) {
          setUserEmail(parsed.email);
        }
      }
    } catch (e) {}

    return () => {
      window.removeEventListener('storage', handleStorageChange);
      window.removeEventListener('wallet-update', syncWalletData);
    };
  }, [syncWalletData]);

  const handleRefresh = () => {
    setLoading(true);
    setTimeout(() => {
      syncWalletData();
      setLoading(false);
    }, 600);
  };

  // ── Top Up Submission handler ──
  const handleTopUpSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setTopUpError('');
    const amt = parseFloat(topUpAmount);

    if (isNaN(amt) || amt <= 0) {
      setTopUpError('Please enter a valid positive amount.');
      return;
    }
    if (amt > 50000) {
      setTopUpError('Maximum top-up amount in Staging Sandbox is ₹50,000.');
      return;
    }

    try {
      const newBalance = balance + amt;
      const formattedDate = new Date().toLocaleDateString('en-IN', {
        day: 'numeric',
        month: 'short',
        year: 'numeric',
      });
      const newTx: Transaction = {
        id: `TX-${Math.floor(1000 + Math.random() * 9000)}`,
        type: 'credit',
        desc: 'Staging Wallet Top-Up',
        amount: `+₹${amt.toLocaleString('en-IN', { minimumFractionDigits: 2 })}`,
        date: formattedDate,
        status: 'Completed',
      };

      const updatedTxs = [newTx, ...transactions];

      // Commit topup updates
      localStorage.setItem(WALLET_BALANCE_KEY, String(newBalance));
      localStorage.setItem(WALLET_TXS_KEY, JSON.stringify(updatedTxs));

      // Dispatch refresh triggers
      window.dispatchEvent(new Event('wallet-update'));

      // Clean form states
      setTopUpAmount('');
      setShowTopUp(false);
    } catch (err) {
      setTopUpError('Failed to top up wallet. Storage quota exceeded.');
    }
  };

  return (
    <div className="w-full flex-1 flex flex-col p-4 md:p-8 selection:bg-rose-500/30">
      <motion.div
        variants={containerVariants}
        initial="hidden"
        animate="show"
        className="max-w-4xl mx-auto w-full space-y-6 pb-12"
      >
        {/* Header */}
        <motion.div variants={cardVariants} className="flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="p-3 bg-primary/10 border border-primary/20 rounded-xl">
              <Wallet className="w-6 h-6 text-primary" />
            </div>
            <div>
              <h1 className="text-2xl font-bold tracking-tight text-main">
                {t('wallet')}
              </h1>
              <p className="text-xs text-muted">Manage your Trayago credits and rewards balance</p>
            </div>
          </div>

          <motion.button
            whileHover={{ scale: 1.08 }}
            whileTap={{ scale: 0.93 }}
            onClick={handleRefresh}
            className="w-10 h-10 flex items-center justify-center bg-input hover:bg-card text-secondary hover:text-main rounded-xl border border-subtle transition-all touch-manipulation"
            title="Refresh balance"
          >
            <motion.div animate={loading ? { rotate: 360 } : { rotate: 0 }} transition={{ repeat: loading ? Infinity : 0, duration: 0.7, ease: 'linear' as const }}>
              <RefreshCw className="w-4 h-4" />
            </motion.div>
          </motion.button>
        </motion.div>

        {/* Balance Cards Grid */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">

          {/* Main Wallet Balance Card */}
          <motion.div
            variants={cardVariants}
            whileHover={{ y: -4, transition: { type: 'spring' as const, stiffness: 400, damping: 22 } }}
            className="relative overflow-hidden bg-gradient-to-br from-primary/10 to-card border border-primary/20 rounded-3xl p-6 shadow-2xl flex flex-col justify-between h-44"
          >
            <div className="absolute -right-4 -bottom-4 w-28 h-28 bg-primary/8 rounded-full blur-2xl pointer-events-none" />
            <div className="absolute top-4 right-4 opacity-10">
              <Wallet className="w-10 h-10 text-primary" />
            </div>
            <div>
              <span className="text-xs font-bold text-muted uppercase tracking-widest block">{t('available_balance')}</span>
              <span className="text-3xl font-black text-main mt-1 block">
                ₹{animatedBalance.toLocaleString('en-IN', { minimumFractionDigits: 2 })}
              </span>
            </div>
            <div className="flex items-center justify-between border-t border-primary/15 pt-4">
              <span className="text-xs text-secondary max-w-[160px] truncate">{userEmail}</span>
              {process.env.NODE_ENV !== 'production' && (
                <motion.button
                  whileHover={{ scale: 1.04 }}
                  whileTap={{ scale: 0.95 }}
                  onClick={() => setShowTopUp(true)}
                  className="px-4 py-1.5 bg-primary hover:opacity-90 text-white font-bold text-xs rounded-xl shadow-md shadow-primary/20 transition-colors flex items-center gap-1.5"
                >
                  <PlusCircle size={14} />
                  {t('add_money')}
                </motion.button>
              )}
            </div>
          </motion.div>

          {/* Loyalty Rewards Points Card */}
          <motion.div
            variants={cardVariants}
            whileHover={{ y: -4, transition: { type: 'spring' as const, stiffness: 400, damping: 22 } }}
            className="relative overflow-hidden bg-gradient-to-br from-violet-500/10 to-card border border-violet-500/20 rounded-3xl p-6 shadow-2xl flex flex-col justify-between h-44"
          >
            <div className="absolute -right-4 -bottom-4 w-28 h-28 bg-violet-500/8 rounded-full blur-2xl pointer-events-none" />
            <div className="absolute top-4 right-4 opacity-10">
              <Coins className="w-10 h-10 text-violet-400" />
            </div>
            <div>
              <span className="text-xs font-bold text-muted uppercase tracking-widest block">{t('reward_coins')}</span>
              <span className="text-3xl font-black text-violet-600 dark:text-violet-400 mt-1 block">
                {animatedPoints} <span className="text-xs font-semibold text-violet-500">Points</span>
              </span>
            </div>
            <div className="flex items-center justify-between border-t border-violet-500/15 pt-4">
              <span className="text-xs text-secondary flex items-center gap-1">
                <Award className="w-3.5 h-3.5 text-violet-400" /> Earned via referrals
              </span>
              <motion.button
                whileHover={{ scale: 1.04 }}
                whileTap={{ scale: 0.95 }}
                onClick={() => alert('Redemption will open in the next release.')}
                className="px-4 py-1.5 bg-violet-500/10 hover:bg-violet-500/20 text-violet-600 dark:text-violet-400 border border-violet-500/20 font-bold text-xs rounded-xl transition-colors"
              >
                {t('redeem_points')}
              </motion.button>
            </div>
          </motion.div>
        </div>

        {/* Transaction History */}
        <motion.div variants={cardVariants} className="bg-card border border-subtle rounded-3xl p-6 shadow-2xl">
          <h3 className="font-extrabold text-main text-md tracking-tight mb-4 flex items-center gap-2">
            <TrendingUp className="w-4 h-4 text-blue-500" /> {t('transaction_history')}
            <span className="ml-auto text-[10px] text-muted font-mono">{transactions.length} entries</span>
          </h3>

          {transactions.length === 0 ? (
            <div className="text-center py-10 space-y-2">
              <Wallet className="w-10 h-10 text-muted mx-auto opacity-30" />
              <p className="text-xs text-muted">No transactions yet.</p>
            </div>
          ) : (
            <div className="divide-y divide-subtle">
              {transactions.map((tx, i) => {
                const isCredit = tx.type === 'credit';
                return (
                  <motion.div
                    key={tx.id}
                    custom={i}
                    variants={txVariants}
                    initial="hidden"
                    animate="show"
                    className={`py-4 flex items-center justify-between gap-4 border-l-2 pl-3 -ml-3 ${
                      isCredit ? 'border-l-emerald-500/40' : 'border-l-red-500/40'
                    }`}
                  >
                    <div className="flex items-center gap-3">
                      <div className={`w-10 h-10 rounded-xl flex items-center justify-center border shrink-0 ${
                        isCredit
                          ? 'bg-emerald-500/10 border-emerald-500/20 text-emerald-600 dark:text-emerald-400'
                          : 'bg-red-500/10 border-red-500/20 text-red-600 dark:text-red-400'
                      }`}>
                        {isCredit ? <ArrowDownLeft className="w-5 h-5" /> : <ArrowUpRight className="w-5 h-5" />}
                      </div>
                      <div>
                        <h4 className="font-bold text-sm text-main leading-snug">{tx.desc}</h4>
                        <p className="text-[10px] text-muted font-mono mt-0.5">{tx.id} • {tx.date}</p>
                      </div>
                    </div>

                    <div className="text-right">
                      <span className={`font-black text-sm block ${isCredit ? 'text-emerald-600 dark:text-emerald-400' : 'text-secondary'}`}>
                        {tx.amount}
                      </span>
                      <span className="text-[9px] text-muted flex items-center gap-1 justify-end font-semibold">
                        <ShieldCheck className="w-3.5 h-3.5 text-emerald-500" /> {tx.status}
                      </span>
                    </div>
                  </motion.div>
                );
              })}
            </div>
          )}
        </motion.div>
      </motion.div>

      {/* ── Top-Up Modal ── */}
      <AnimatePresence>
        {showTopUp && process.env.NODE_ENV !== 'production' && (
          <motion.div
            key="topup-backdrop"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/70 backdrop-blur-md"
          >
            <motion.div
              key="topup-modal"
              variants={modalVariants}
              initial="hidden"
              animate="show"
              exit="exit"
              className="relative w-full max-w-sm bg-card border border-subtle rounded-3xl p-6 shadow-2xl"
            >
              <motion.button
                whileHover={{ scale: 1.1 }}
                whileTap={{ scale: 0.9 }}
                onClick={() => { setShowTopUp(false); setTopUpAmount(''); setTopUpError(''); }}
                className="absolute right-4 top-4 w-8 h-8 rounded-full bg-input hover:bg-card flex items-center justify-center text-secondary hover:text-main transition-colors"
              >
                <X size={16} />
              </motion.button>

              <h3 className="text-lg font-black text-main flex items-center gap-2 mb-2">
                <Wallet className="w-5 h-5 text-blue-500" /> Add Money to Wallet
              </h3>
              <p className="text-xs text-secondary mb-6">Enter mock top-up credits. Transactions are simulated for staging testing.</p>

              <form onSubmit={handleTopUpSubmit} className="space-y-4">
                <div className="space-y-1.5">
                  <label className="text-[10px] font-bold text-muted uppercase tracking-wider pl-1">Amount (₹)</label>
                  <input
                    type="number"
                    placeholder="e.g. 500"
                    value={topUpAmount}
                    onChange={(e) => setTopUpAmount(e.target.value)}
                    className="w-full bg-input border border-subtle rounded-2xl py-3.5 px-5 text-sm font-bold text-main outline-none focus:border-blue-500 transition-all font-mono"
                    autoFocus
                    required
                  />
                </div>

                <AnimatePresence>
                  {topUpError && (
                    <motion.p
                      initial={{ opacity: 0, y: -6 }}
                      animate={{ opacity: 1, y: 0 }}
                      exit={{ opacity: 0 }}
                      className="text-[10px] font-semibold text-red-500 uppercase tracking-wide"
                    >
                      ⚠️ {topUpError}
                    </motion.p>
                  )}
                </AnimatePresence>

                <motion.button
                  whileHover={{ scale: 1.01 }}
                  whileTap={{ scale: 0.97 }}
                  type="submit"
                  className="w-full py-4 rounded-2xl bg-blue-600 hover:bg-blue-700 text-white font-black uppercase text-xs tracking-widest transition-all shadow-md"
                >
                  Confirm Top-Up
                </motion.button>
              </form>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}
